// The printer model catalogue: every Bambu Lab model the app knows, what it can do, and how to reach it.
// Two layers: models.generated.ts holds what Bambu Studio's resources/printers/<code>.json files say
// (regenerated by app/tools/gen-printer-models.ts at the pin in slicer/upstream.lock); this file adds
// the facts those files do not carry, each citing its source. Runtime evidence wins over both: the
// feature bits a printer reports (PrinterSnapshot.firmwareSupport) override these for what they cover.
import { GENERATED_MODELS, type GeneratedModel } from './models.generated';
import type { VersionModule } from './status';

export const MODEL_CODES = [
	'BL-P001',
	'BL-P002',
	'C13',
	'C11',
	'C12',
	'N1',
	'N2S',
	'N9',
	'N7',
	'N6',
	'O1D',
	'O1E',
	'O1S',
	'O1C',
	'O1C2'
] as const;
export type ModelCode = (typeof MODEL_CODES)[number];
export type Series = 'X1' | 'P1' | 'A1' | 'A2' | 'P2' | 'H2' | 'X2';
/**
 * How the live camera is reached on the LAN. The catalogue gives the default; the live report decides
 * (`ipcam.rtsp_url`: "rtsps://…" → rtsps, "rtsp://…" → rtsp on port 554, "disable" → off until the
 * user enables LAN liveview), as Bambu Studio DeviceManager.cpp ~3450 does.
 */
export type CameraProtocol = 'rtsps' | 'rtsp' | 'jpeg6000' | 'none';

export interface Capabilities {
	/** support_chamber_temp_display, else support_chamber (Bambu Studio DevConfig.cpp). */
	chamberTempDisplay: boolean;
	/** support_chamber_temp_edit. */
	chamberTempEdit: boolean;
	/** support_aux_fan. */
	auxFan: boolean;
	/** support_chamber_fan. */
	chamberFan: boolean;
	/** ha-bambulab Features.SECONDARY_AUX_FAN (P2S, X2D). */
	secondaryAuxFan: boolean;
	/** ha-bambulab Features.AIRDUCT_MODE (H2, P2S, X2D). */
	airductMode: boolean;
	/** support_lidar_calibration. */
	lidar: boolean;
	/** support_ai_monitoring. */
	aiMonitoring: boolean;
	/** support_first_layer_inspect. */
	firstLayerInspect: boolean;
	/** support_build_plate_marker_detect. */
	buildPlateMarkerDetect: boolean;
	/** support_ams_humidity. */
	amsHumidity: boolean;
	/** ha-bambulab Features.AMS_DRYING (per-model firmware gates). */
	amsDrying: boolean;
	/** ha-bambulab Features.AMS_DRYING_SETTINGS. */
	amsDryingSettings: boolean;
	/** support_command_ams_switch. */
	amsSwitchCommand: boolean;
	/** ha-bambulab Features.AMS_READ_RFID_COMMAND. */
	amsReadRfid: boolean;
	/** ha-bambulab dual_nozzle_printers (H2C, H2D, H2D Pro, X2D). */
	dualNozzle: boolean;
	/** ha-bambulab Features.EXTRUDER_TOOL (H2 laser/cutter head). */
	extruderTool: boolean;
	/** lights_report "work_light" (X1 series; the X2D reports it too: ha-bambulab MOCK-X2D.json). */
	workLight: boolean;
	/** ha-bambulab Features.CHAMBER_LIGHT_2 (H2, X2). */
	chamberLight2: boolean;
	/** ha-bambulab Features.HEATBED_LIGHT (H2). */
	heatbedLight: boolean;
	/** ha-bambulab Features.DOOR_SENSOR (with firmware gates). */
	doorSensor: boolean;
	/** ha-bambulab Features.PROMPT_SOUND (A1, A2, H2, P2, X2; also needs Developer Mode). */
	promptSound: boolean;
	/** support_timelapse. */
	timelapse: boolean;
	/** support_send_to_sd. */
	sendToSd: boolean;
	/** support_print_without_sd. */
	printWithoutSd: boolean;
	/** support_motor_noise_cali. */
	motorNoiseCali: boolean;
	/** support_flow_calibration. */
	flowCalibration: boolean;
	/** support_auto_flow_calibration. */
	autoFlowCalibration: boolean;
	/** support_nozzle_offset_calibration. */
	nozzleOffsetCalibration: boolean;
	/** support_bed_leveling > 0. */
	bedLeveling: boolean;
	/** support_user_preset. */
	userPreset: boolean;
	/** ha-bambulab Features.K_VALUE (A1, A2, P1). */
	kValueInReport: boolean;
	/** ha-bambulab Features.ACTIVE_CHAMBER_HEATER (X1E, H2, X2). */
	activeChamberHeater: boolean;
	/** ha-bambulab Features.FIRE_ALARM_BUZZER (H2); buzzer_ctrl. */
	fireAlarmBuzzer: boolean;
	/** ha-bambulab Features.HOTEND_RACK (H2C with a rack reported); also fun bit 60 at runtime. */
	hotendRack: boolean;
	/** P1 firmware ≥ 01.07.00.00 ignores LAN commands while also cloud-connected (ha-bambulab Features.HYBRID_MODE_BLOCKS_CONTROL): warn, do not block. */
	hybridModeBlocksControl: boolean;
	/** Firmware where Developer Mode is required for LAN control (ha-bambulab Features.MQTT_ENCRYPTION_FIRMWARE): drives the setup help text. */
	developerModeRequired: boolean;
}

export interface PrinterModel {
	code: ModelCode;
	/** Bambu Studio machine model name, e.g. "Bambu Lab X1 Carbon" (also the profile machine_model name). */
	name: string;
	/** "X1C", "P1S", "A1 mini", "H2D", "X2D"… */
	short: string;
	series: Series;
	/** Serial-number prefix Bambu's HMS data uses for this model ("00M", "094"…), null when unknown. */
	hmsDevice: string | null;
	/** X1 series send full push_status; others send deltas (OpenBambuAPI mqtt.md "push_status"). */
	reports: 'full' | 'delta';
	camera: CameraProtocol;
	nozzles: 1 | 2;
	/**
	 * project_file url form: 'sdcard' → file:///sdcard/<name>, 'ftp' → ftp:///<name>. The references
	 * disagree for some models: see PRINT_URL_UNVERIFIED.
	 */
	printUrl: 'sdcard' | 'ftp';
	/** printer_is_enclosed. */
	enclosed: boolean;
	/** nozzle_temp_range[1]. */
	nozzleTempMax: number;
	/** bed_temp_range[1] / bed_temperature_limit, else Bambu Studio's BED_TEMP_LIMIT (120). */
	bedTempMax: number;
	/** support_chamber_temp_edit_range[1]. */
	chamberTempMax: number | null;
	/** At firmware 00.00.00.00. */
	caps: Capabilities;
	/** Version-gated overrides, ascending by firmware version. */
	firmwareCaps: { from: string; caps: Partial<Capabilities> }[];
}

/**
 * Models whose project_file url form is not settled. ha-bambulab (0e027ff) contradicts itself:
 * const.py LEGACY_SDCARD_PRINTERS (defined, never used) implies ftp:/// for every model not listed,
 * while the path that runs, coordinator.py _service_call_print_project_file ~720–727, sends ftp:///
 * only for the H2C, H2S and H2D and file:///sdcard/ for everything else, these four included. We keep
 * ftp:/// and BambuPrinter.startPrint retries once with file:///sdcard/ (the upload lands in the
 * storage root, which both forms name), logging which one worked so real diagnostics can settle it.
 */
export const PRINT_URL_UNVERIFIED: ReadonlySet<ModelCode> = new Set(['N9', 'N7', 'N6', 'O1E']);

