// Model groups as ha-bambulab's Device.supports_feature names them (pybambu/models.py).
const A1: ModelCode[] = ['N1', 'N2S'];
const A2: ModelCode[] = ['N9'];
const H2: ModelCode[] = ['O1C', 'O1C2', 'O1D', 'O1E', 'O1S'];
const P1: ModelCode[] = ['C11', 'C12'];
const P2: ModelCode[] = ['N7'];
const X1: ModelCode[] = ['BL-P001', 'BL-P002'];
const X1E: ModelCode[] = ['C13'];
const X2: ModelCode[] = ['N6'];
const H2C: ModelCode[] = ['O1C', 'O1C2'];
const in_ = (code: ModelCode, ...groups: ModelCode[][]) => groups.some((g) => g.includes(code));

type Gate = { from: string } | boolean;
/** A capability that is true on some models from a firmware version on (ha-bambulab supports_sw_version). */
function gate(code: ModelCode, rules: [ModelCode[], Gate][], otherwise: boolean): Gate {
	for (const [group, rule] of rules) if (group.includes(code)) return rule;
	return otherwise;
}

/** ha-bambulab Device.supports_feature, per model (pybambu/models.py at 0e027ff). */
function haFacts(code: ModelCode): Record<string, Gate> {
	return {
		secondaryAuxFan: in_(code, P2, X2),
		airductMode: in_(code, H2, P2, X2),
		amsDrying: gate(
			code,
			[
				[A1, { from: '01.06.10.33' }],
				[P1, { from: '01.07.50.18' }],
				[X1E, false],
				[X1, { from: '01.08.50.18' }]
			],
			true
		),
		amsDryingSettings: gate(
			code,
			[
				[P2, { from: '01.01.50.40' }],
				[H2C, { from: '01.01.50.00' }]
			],
			false
		),
		amsReadRfid: gate(
			code,
			[
				[A1, { from: '01.06.00.00' }],
				[P1, { from: '01.08.01.00' }],
				[X1E, false],
				[X1, { from: '01.09.00.00' }]
			],
			true
		),
		dualNozzle: in_(code, ['O1C', 'O1C2', 'O1D', 'O1E', 'N6']),
		extruderTool: in_(code, H2, X2),
		workLight: in_(code, X1, X1E, X2),
		chamberLight2: in_(code, H2, X2),
		heatbedLight: in_(code, H2),
		doorSensor: gate(
			code,
			[
				[H2, true],
				[P2, true],
				[X2, true],
				[X1E, { from: '01.01.02.00' }],
				[X1, { from: '01.07.00.00' }]
			],
			false
		),
		promptSound: in_(code, A1, A2, H2, P2, X2),
		kValueInReport: in_(code, A1, A2, P1),
		activeChamberHeater: in_(code, X1E, H2, X2),
		fireAlarmBuzzer: in_(code, H2),
		hotendRack: in_(code, H2C),
		hybridModeBlocksControl: gate(code, [[P1, { from: '01.07.00.00' }]], false),
		developerModeRequired: gate(
			code,
			[
				[A1, { from: '01.05.00.00' }],
				[['O1D', 'O1E'], { from: '01.01.00.00' }],
				[P1, { from: '01.08.02.00' }],
				[X1E, false],
				[X1, { from: '01.08.50.32' }]
			],
			true
		)
	};
}

function build(code: ModelCode): PrinterModel {
	const g: GeneratedModel | undefined = GENERATED_MODELS[code];
	if (!g) throw new Error(`No capability data for ${code}; run tools/gen-printer-models.ts.`);
	const facts = haFacts(code);
	const base = { ...g.caps } as Record<string, boolean>;
	const gated: { from: string; caps: Partial<Capabilities> }[] = g.firmwareCaps.map((f) => ({
		from: f.from,
		caps: f.caps as Partial<Capabilities>
	}));
	for (const [key, rule] of Object.entries(facts)) {
		base[key] = rule === true;
		if (typeof rule === 'object')
			gated.push({ from: rule.from, caps: { [key]: true } as Partial<Capabilities> });
	}
	gated.sort((a, b) => compareFirmware(a.from, b.from));
	return {
		code,
		name: g.displayName,
		...TABLE[code],
		reports: in_(code, X1, X1E) ? 'full' : 'delta',
		enclosed: g.enclosed,
		nozzleTempMax: g.nozzleTempMax,
		bedTempMax: g.bedTempMax,
		chamberTempMax: g.chamberTempMax,
		caps: base as unknown as Capabilities,
		firmwareCaps: gated
	};
}

export const PRINTER_MODELS = Object.fromEntries(MODEL_CODES.map((c) => [c, build(c)])) as Record<
	ModelCode,
	PrinterModel
>;

export const isModelCode = (code: unknown): code is ModelCode =>
	typeof code === 'string' && (MODEL_CODES as readonly string[]).includes(code);

export function modelByCode(code: string): PrinterModel | null {
	return isModelCode(code) ? PRINTER_MODELS[code] : null;
}

/** Models grouped by series, in catalogue order (for pickers). */
export function modelsBySeries(): { series: Series; models: PrinterModel[] }[] {
	const out: { series: Series; models: PrinterModel[] }[] = [];
	for (const code of MODEL_CODES) {
		const m = PRINTER_MODELS[code];
		// O1C and O1C2 are the same printer to people; offer one.
		if (code === 'O1C') continue;
		const group = out.find((g) => g.series === m.series);
		if (group) group.models.push(m);
		else out.push({ series: m.series, models: [m] });
	}
	return out;
}

/** Whether a file sliced for `sliced` prints on a `printer` (the H2C pair O1C/O1C2 either way). */
export function sameModel(sliced: string, printer: string): boolean {
	if (sliced === printer) return true;
	return H2C.includes(sliced as ModelCode) && H2C.includes(printer as ModelCode);
}

/** A model's short name for messages ("the P1S"), or the raw code when unknown. */
export function modelShort(code: string): string {
	return modelByCode(code)?.short ?? code;
}

/** get_version product_name → model (ha-bambulab utils.get_printer_type product_map). */
const PRODUCT_NAMES: Record<string, ModelCode> = {
	'Bambu Lab A1': 'N2S',
	'Bambu Lab A1 mini': 'N1',
	'Bambu Lab A2L': 'N9',
	'Bambu Lab P1P': 'C11',
	'Bambu Lab P1S': 'C12',
	'Bambu Lab P2S': 'N7',
	// O1C and O1C2 cannot be told apart from the product name; O1C2 is the model id profiles use.
	'Bambu Lab H2C': 'O1C2',
	'Bambu Lab H2D': 'O1D',
	'Bambu Lab H2D Pro': 'O1E',
	'Bambu Lab H2S': 'O1S',
	'Bambu Lab X2D': 'N6',
	// ha-bambulab MOCK-X1CMULTIAMS.json: the X1C's ota module says "Bambu Lab X1-Carbon".
	'Bambu Lab X1-Carbon': 'BL-P001',
	'Bambu Lab X1 Carbon': 'BL-P001',
	'Bambu Lab X1': 'BL-P002',
	'Bambu Lab X1E': 'C13'
};

/**
 * X1-series printers announce a dev_type name in SSDP DevModel, not their code (Bambu Studio
 * DeviceCore/DevConfigUtil.h _parse_printer_type, called from DevManager.cpp on_machine_alive).
 */
const SSDP_ALIASES: Record<string, ModelCode> = {
	'3DPrinter-X1-Carbon': 'BL-P001',
	'3DPrinter-X1': 'BL-P002'
};

/**
 * Model from SSDP DevModel, get_version product_name, or the older AP/project_name heuristics
 * (ha-bambulab utils.get_printer_type). The H2C pair O1C/O1C2 cannot be told apart from
 * product_name: SSDP DevModel wins, else O1C2.
 */
export function detectModel(input: {
	ssdpModel?: string;
	productName?: string;
	modules?: VersionModule[];
}): ModelCode | null {
	const ssdp = input.ssdpModel?.trim();
	if (ssdp && SSDP_ALIASES[ssdp]) return SSDP_ALIASES[ssdp];
	if (ssdp && isModelCode(ssdp)) return ssdp as ModelCode;
	if (input.productName) {
		const hit = PRODUCT_NAMES[input.productName.trim()];
		if (hit) return hit;
	}
	const modules = input.modules ?? [];
	for (const m of modules) {
		const hit = PRODUCT_NAMES[m.product.trim()];
		if (hit) return hit;
	}
	// Legacy: the AP board's hw_ver plus project_name (carried in `product` for these older reports).
	const ap = modules.find((m) => m.hw.startsWith('AP0'));
	if (ap) {
		const project = ap.product;
		if (ap.hw === 'AP02') return 'C13';
		if (project === 'N1') return 'N1';
		if (ap.hw === 'AP04' && project === 'C11') return 'C11';
		if (ap.hw === 'AP04' && project === 'C12') return 'C12';
		if (ap.hw === 'AP05' && project === 'N2S') return 'N2S';
		if (ap.hw === 'AP05' && project === '' && modules.some((m) => m.name === 'rv1126'))
			return 'BL-P001';
	}
	return null;
}

/** Compares "01.07.50.18"-style versions (missing or odd parts count as 0). */
export function compareFirmware(a: string, b: string): number {
	const pa = a.split('.').map((p) => parseInt(p, 10) || 0);
	const pb = b.split('.').map((p) => parseInt(p, 10) || 0);
	for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
		const d = (pa[i] ?? 0) - (pb[i] ?? 0);
		if (d) return d < 0 ? -1 : 1;
	}
	return 0;
}

/** Capabilities for a model at a firmware version (base + every firmwareCaps entry whose `from` ≤ version). */
export function capabilitiesFor(code: ModelCode, firmware: string | null): Capabilities {
	const model = PRINTER_MODELS[code];
	const caps = { ...model.caps };
	if (!firmware) return caps;
	// ha-bambulab supports_sw_version: X1Plus firmware (99.x) behaves like 01.08.02.00.
	const version = compareFirmware(firmware, '99.00.00.00') >= 0 ? '01.08.02.00' : firmware;
	for (const f of model.firmwareCaps)
		if (compareFirmware(f.from, version) <= 0) Object.assign(caps, f.caps);
	return caps;
}
